XDocument doc = XDocument.Load("playerPrefsV2.xml");
var map = doc.Descendants("string").ToDictionary(
    e => e.Attribute("name")!.Value,
    e => e.Value);

List<SongScore> scores = [];
foreach (var (k, v) in map)
{
    string decKey = LocalSave.DecryptLocalSaveStringNew(WebUtility.UrlDecode(k));
    if (!decKey.Contains(".Record.")) continue; // 只取成绩项

    string[] parts = decKey.Split('.');
    string id = string.Join(".", parts.Take(3));
    Difficulty diff = Enum.Parse<Difficulty>(parts[^1]);
    scores.Add(RawScore.FromJson(
        LocalSave.DecryptLocalSaveStringNew(WebUtility.UrlDecode(v)))
        .ToSongScore(id, diff));
}

